-- Unity Catalog DROP statements.
DROP CONNECTION c;

DROP CONNECTION IF EXISTS c;

DROP CREDENTIAL c;

DROP STORAGE CREDENTIAL c FORCE;

DROP SERVICE CREDENTIAL IF EXISTS c;

DROP EXTERNAL LOCATION l;

DROP POLICY p ON CATALOG c;

DROP POLICY p ON TABLE t;

DROP PROCEDURE p;

DROP PROCEDURE IF EXISTS p;

DROP PROVIDER p;

DROP RECIPIENT r;

DROP SHARE s;

DROP TEMPORARY VARIABLE v;

DROP TABLE IF EXISTS t FORCE;

DROP TEMPORARY TABLE t;
